/// <summary>
/// Data contract class for the cover note report
/// </summary>
[DataContract, SysOperationContractProcessing(classStr(METOrderShipmentBundlingReportUIBuilder))]
class METOrderShipmentBundlingReportContract
{
    METOrderTransactionType transactionType;
    boolean         isFirstReport;
    MetShipmentId   shipmentId;
    MetLoadId       loadId;
    boolean         isMultiThreadedJob;
    boolean         isReprint;

}

Method.Source:
/// <summary>
/// Parm method for the load number
/// </summary>
/// <param name = "loadId">the load number</param>
/// <returns>the load number</returns>
[DataMemberAttribute('loadId')]
public MetLoadId parmLoadId(MetLoadId _loadId = loadId)
{
    loadId = _loadId;
    return loadId;
}

/// <summary>
/// Parm method for the shipment number
/// </summary>
/// <param name = "_shipmentId">the shipment number</param>
/// <returns>the shipment number</returns>
[DataMemberAttribute('shipmentId'),
    SysOperationControlVisibilityAttribute(false)]
public MetShipmentId parmShipmentId(MetShipmentId _shipmentId = shipmentId)
{
    shipmentId = _shipmentId;
    return shipmentId;
}

/// <summary>
/// Parm method for the shipment number
/// </summary>
/// <param name = "_isFirstReport">the shipment number</param>
/// <returns>the shipment number</returns>
[DataMemberAttribute('IsFirstReport'),
    SysOperationControlVisibilityAttribute(false)]
public boolean parmIsFirstReport(boolean _isFirstReport = isFirstReport)
{
    isFirstReport = _isFirstReport;
    return isFirstReport;
}

/// <summary>
/// Parm method for the transaction type
/// </summary>
/// <param name = "_transactionType">the shipment number</param>
/// <returns>the shipment number</returns>
[DataMemberAttribute('TransactionType'),
    SysOperationControlVisibilityAttribute(false)]
public METOrderTransactionType parmTransactionType(METOrderTransactionType _transactionType = transactionType)
{
    transactionType = _transactionType;
    return transactionType;
}

/// <summary>
/// Gets and sets IsMultithreadedJob.
/// </summary>
/// <param name = "_isMultiThreadedJob">IsMultithreadedJob.</param>
/// <returns>IsMultithreadedJob.</returns>
[DataMemberAttribute('IsMultithreadedJob'),
    SysOperationControlVisibilityAttribute(false)]
public boolean parmIsMultiThreadedJob(boolean _isMultiThreadedJob = isMultiThreadedJob)
{
    isMultiThreadedJob = _isMultiThreadedJob;
    return isMultiThreadedJob;
}

/// <summary>
/// get and set IsReprint
/// </summary>
/// <param name = "_isReprint">isReprint</param>
/// <returns>isReprint</returns>
[DataMemberAttribute('isReprint'),
    SysOperationControlVisibilityAttribute(false)]
public boolean parmIsReprint(boolean _isReprint = isReprint)
{
    isReprint = _isReprint;
    return isReprint;
}
